// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address caller, bytes32 role, address account) public {
        vm.assume(caller != address(this));
        vm.assume(account != caller);
        vm.assume(account != address(this));
        vm.assume(caller != address(0) && account != address(0));

        bool before = c.hasRole(role, account);

        vm.prank(caller);
        bool ok;
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: an attempt to renounce a role on behalf of ANOTHER account must
        // always revert, and role membership must remain untouched. The mutant
        // lets this call succeed (and revokes the foreign account), breaking it.
        assertTrue(!ok && c.hasRole(role, account) == before);
    }
}
